#include "farm_map_screen.hh"
#include "calendar.hh"
#include "game_state.hh"
#include "hardware_blend.hh"

void * operator new(unsigned long);

#include "gbaio.h"

static inline volatile u16 * GetFarmMapTilemapEntry(u32 screen_block, u32 x, u32 y)
{
    u32 block = (y >> 5) * 2 + (x >> 5) + screen_block;
    return reinterpret_cast<volatile u16 *>(BG_SCREEN_ADDR(block)
        + (y & 31) * 32 * sizeof(u16) + (x & 31) * sizeof(u16));
}

void FarmMapScreenCore::FadeIn()
{
    GetHardwareDisplayState(reinterpret_cast<void * const *>(this))->SetBlendControl(BLDCNT_TGT1_ALL);
    HardwareBlendObject blend(GetHardwareDisplayState(reinterpret_cast<void * const *>(this)));
    blend.blend.Begin(0x889, 1, 1);
    GetHardwareCommandList(reinterpret_cast<void * const *>(this))->Append(&blend);
    while (blend.IsLinked()) {
        RenderMarkers();
        UpdateHardwareFrame(this);
    }
}

void FarmMapScreenCore::FadeOut()
{
    GetHardwareDisplayState(reinterpret_cast<void * const *>(this))->SetBlendControl(BLDCNT_TGT1_ALL);
    HardwareBlendObject blend(GetHardwareDisplayState(reinterpret_cast<void * const *>(this)));
    blend.blend.End(0x889, 1, 1);
    GetHardwareCommandList(reinterpret_cast<void * const *>(this))->Append(&blend);
    while (blend.IsLinked()) {
        RenderMarkers();
        UpdateHardwareFrame(this);
    }
}

