void FarmMapScreenCore::CopyTilemapRect(u32 screen_block, u32 x, u32 y,
    u32 width, u32 height, u16 const * tilemap)
{
    u32 max_x = x + width;
    u32 max_y = y + height;
    for (; y < max_y; ++y) {
        for (u32 column = x; column < max_x; ++column) {
            volatile u16 * destination = GetFarmMapTilemapEntry(screen_block, column, y);
            *destination = *tilemap++;
        }
    }
}

